package com.swingtrade.data.store;
import com.swingtrade.data.entity.BacktestResultEntity; import com.swingtrade.data.repository.BacktestResultRepository; import com.swingtrade.domain.BacktestResult; import com.swingtrade.domain.store.BacktestResultStore; import org.springframework.stereotype.Service; import java.time.LocalDate; import java.util.Optional;
@Service public class BacktestResultStoreImpl implements BacktestResultStore { private final BacktestResultRepository repo; public BacktestResultStoreImpl(BacktestResultRepository repo){this.repo=repo;} public Optional<BacktestResult> findBySymbolAndDate(String s,LocalDate d){return repo.findBySymbolAndRunDate(s,d).map(BacktestResultEntity::toDomain);} public BacktestResult save(BacktestResult r){return repo.save(BacktestResultEntity.fromDomain(r)).toDomain();} public BacktestResult saveOrUpdate(BacktestResult r){var e=repo.findBySymbolAndRunDate(r.symbol(),r.runDate()).orElseGet(BacktestResultEntity::new); var n=BacktestResultEntity.fromDomain(r); n.setId(e.getId()); return repo.save(n).toDomain();} }
